def _profile_list_refresh_required_warning(reason_code: str) -> str:
    if reason_code == "profile_list_refresh_target_unresolved":
        return (
            "DB Profile 一覧の差分同期対象を安全に特定できませんでした。"
            "DB Profile 一覧を再取得してください。"
        )
    if reason_code == "profile_list_refresh_submit_failed":
        return (
            "DB Profile 一覧の差分同期を開始できませんでした。DB Profile 一覧を再取得してください。"
        )
    return "DB Profile 一覧の差分同期で不整合を検出しました。DB Profile 一覧を再取得してください。"


_ORACLE_ERROR_CODE_RE = re.compile(r"\b(?:ORA|DPY|DPI)-\d{4,5}\b", re.IGNORECASE)
_ORACLE_CONNECTION_CODES = frozenset(
    {
        "ORA-01012",
        "ORA-01017",
        "ORA-03113",
        "ORA-03114",
        "ORA-03135",
        "ORA-12154",
        "ORA-12505",
        "ORA-12506",
        "ORA-12514",
        "ORA-12541",
        "DPY-4011",
        "DPY-6000",
        "DPY-6005",
        "DPI-1047",
        "DPI-1072",
    }
)
_ORACLE_SCHEMA_COMPATIBILITY_CODES = frozenset({"ORA-00904", "ORA-00942"})


def _display_qualified_name(owner: str, object_name: str) -> str:
    """表示用の `OWNER.OBJECT`。owner が無い・識別子が不正なときは空文字（推測で補わない）。"""

    if not owner.strip() or not object_name.strip():
        return ""
    try:
        return qualified_object_name(owner, object_name)
    except ValueError:
        return ""


def _is_named_table_reference(table: SqlTableReference) -> bool:
    """名前を持つ表参照（schema object）かを返す。

    `JSON_TABLE(...)` / `XMLTABLE(...)` / `TABLE(...)` のような表関数は表名を持たないため、
    表スコープ判定の対象外にする。中のサブクエリの表は別の表参照として判定され、
    関数は `_dangerous_oracle_function_names` で判定される。
    """

    return bool(table.name.strip())


def _is_dual_table_reference(table: SqlTableReference) -> bool:
    """owner 省略の `DUAL` と `SYS.DUAL` を返す（`APP.DUAL` のような他 schema の表は含めない）。"""

    def _token(value: str, quoted: bool) -> str:
        return value if quoted else value.upper()

    if table.catalog or _token(table.name, table.name_quoted) != "DUAL":
        return False
    return not table.owner or _token(table.owner, table.owner_quoted) == "SYS"


def _sql_table_reference_parts(table: SqlTableReference, current_owner: str) -> tuple[str, str]:
    """SQL の表参照を owner / 表名の canonical token にする（owner 省略時は current schema）。

    引用なしは大文字、引用ありは書かれたとおり（`SALES."Mixed_Case"` は `MIXED_CASE` と別の表）。
    """

    owner = (
        sql_identifier_token(table.owner, quoted=table.owner_quoted)
        if table.owner
        else (format_object_part(current_owner.upper()) if current_owner.strip() else "")
    )
    return owner, sql_identifier_token(table.name, quoted=table.name_quoted)


def _graph_with_resolved_table_owners(
    graph: SqlSemanticGraph | None, current_owner: str
) -> SqlSemanticGraph | None:
    """SQL 参照表に表示用の所有者付き名前を付ける。

    owner が SQL に無い表は current schema で補う（`_extract_referenced_tables` と同じ規則）。
    CTE は schema object ではないため補わない。
    """

    if graph is None:
        return None
    tables = []
    for table in graph.tables:
        if table.is_cte or not _is_named_table_reference(table):
            tables.append(table)
            continue
        owner, name = _sql_table_reference_parts(table, current_owner)
        tables.append(
            table.model_copy(
                update={
                    "resolved_owner": normalize_object_part(owner) if owner else "",
                    "resolved_qualified_name": f"{owner}.{name}" if owner and name else "",
                }
            )
        )
    return graph.model_copy(update={"tables": tables})


def _safe_oracle_error_code(exc: Exception) -> str:
    match = _ORACLE_ERROR_CODE_RE.search(str(exc))
    return match.group(0).upper() if match else ""


# ジョブの失敗の利用者向けの文（1 文目に何が起きたか、次に次の操作）。
# 例外・Oracle のエラーの元の文は error_detail に分け、画面は「詳細」に畳んで出す
# （messaging.md §10.3。#1072）。
_JOB_FAILED_MESSAGE = (
    "SQL の生成に失敗しました。時間をおいてもう一度実行してください。"
    "繰り返し失敗するときは、「詳細」の内容を管理者に伝えてください。"
)
# 公開版の業務定義が、公開の後の業務プロファイル・DB の構造（スキーマ）の変更で使えない（#1827）。
# 時間をおいても直らないので「もう一度」と案内せず、管理者が再検証・公開する所を出す。
_PROFILE_REVALIDATION_REQUIRED_MESSAGE = (
    "この業務プロファイルの業務定義（公開版のオントロジー）は、公開の後に業務プロファイルか "
    "DB の構造（スキーマ）が変わったため、SQL の生成に使えません。時間をおいても直りません。"
    "管理者に、「オントロジー構築」でこの業務プロファイルの Markdown を確認し直して公開するよう"
    "依頼してください。"
)
_SQL_EXECUTION_FAILED_MESSAGE = (
    "生成した SQL の実行に失敗しました。"
    "生成した SQL と「詳細」の Oracle のエラーを確認し、質問を言い換えて実行し直してください。"
)
_JOB_FAILURE_DETAIL_MAX_LENGTH = 4000


def _job_failure_detail(exc: BaseException) -> str | None:
    detail = str(exc).strip()
    if not detail:
        return type(exc).__name__
    if len(detail) > _JOB_FAILURE_DETAIL_MAX_LENGTH:
        return detail[:_JOB_FAILURE_DETAIL_MAX_LENGTH] + "…"
    return detail


def _find_business_scope_changed(exc: BaseException | None) -> OntologyGateBlockedError | None:
    """例外（原因の連鎖を含む）から、公開版の業務定義の再検証が要るゲートの拒否を探す（#1827）。"""
    seen: set[int] = set()
    current = exc
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        if (
            isinstance(current, OntologyGateBlockedError)
            and current.code == BUSINESS_SCOPE_CHANGED_CODE
        ):
            return current
        current = current.__cause__ or current.__context__
    return None


def _job_failure_presentation(exc: BaseException) -> tuple[str, str | None]:
    """失敗したジョブの `(error_message, error_detail)`。

    DB 構造の未取得（SCHEMA_CATALOG_EMPTY）は、例外の文がそのまま利用者向けの文と次の操作なので
    1 文目に出す。それ以外は例外の文（ORA-… など）を詳細に分ける。
    """
    if isinstance(exc, SchemaCatalogEmptyError):
        return str(exc), None
    scope_changed = _find_business_scope_changed(exc)
    if scope_changed is not None:
        # 業務定義の再検証が要る（#1827）。ゲートの文とコードは管理者が確かめる「詳細」に残す。
        return (
            _PROFILE_REVALIDATION_REQUIRED_MESSAGE,
            f"{scope_changed.message_ja}（{scope_changed.code}）",
        )
    enterprise_error = find_enterprise_ai_error(exc)
    if enterprise_error is not None and enterprise_error.configuration_error:
        # OCI Enterprise AI の設定の誤り（401 / 403 / 404 / モデルが無い 400）は、時間をおいても
        # 直らないので「もう一度」と案内せず、どのモデル・接続の呼び出しが失敗したかと確かめる所を
        # 出す（#1684）。元の文は詳細に残す。
        return (
            enterprise_ai_configuration_failure_message(enterprise_error, "SQL の生成で "),
            _job_failure_detail(exc),
        )
    return _JOB_FAILED_MESSAGE, _job_failure_detail(exc)


def _job_failure_error_code(exc: BaseException, *, fallback: str) -> str:
    """失敗したジョブの `error_code`（#847）。

    例外（原因の連鎖を含む）の Oracle のコード（`ORA-04027` など）の先頭、無ければ `fallback`。
    `null` のまま返さない（MCP の呼び出し側が失敗を分類できるようにする）。
    """
    if _find_business_scope_changed(exc) is not None:
        # 時間をおいても直らない（業務定義の再検証と公開が要る）ことを MCP の呼び出し側
        # （外部の Agent）が error_code で判断し、再試行を繰り返さないようにする（#1827）。
        return PROFILE_REVALIDATION_REQUIRED_ERROR_CODE
    codes = oracle_error_codes(exc)
    if codes:
        return codes[0]
    # OCI Enterprise AI の HTTP の失敗は種類の分かるコード
    # （ENTERPRISE_AI_AUTHORIZATION_FAILED など。3 製品で共通の対応表。#1684）。
    enterprise_error = find_enterprise_ai_error(exc)
    if enterprise_error is not None and enterprise_error.http_failure is not None:
        return enterprise_error.http_failure.error_code
    return fallback


# チャットのジョブの中で実行した結果の行を、画面が受け取るまで置く文書の collection（#1176）。
_CHAT_RESULTS_COLLECTION = "chat_results"


def _chat_result_alive(document: Mapping[str, Any]) -> bool:
    """受け取りの期限の前か（期限の無い・読めない文書は期限切れとして扱う）。"""
    try:
        expires_at = datetime.fromisoformat(str(document.get("expires_at") or ""))
    except ValueError:
        return False
    if expires_at.tzinfo is None:
        expires_at = expires_at.replace(tzinfo=UTC)
    return expires_at > datetime.now(UTC)


def _chat_execution_summary(
    data: SqlChatExecuteData, *, result_expires_at: str | None = None
) -> SqlChatExecutionSummary:
    """チャットの実行の結果から、ターンに残す要約（行は持たない。#1154）を作る。"""
    return SqlChatExecutionSummary(
        status=data.status,
        executed_at=data.executed_at,
        elapsed_ms=data.elapsed_ms,
        row_count=data.results.total,
        column_count=len(data.results.columns),
        has_more=bool(data.results.has_more or data.results.truncated),
        error_code=data.error_code,
        history_id=data.history_id,
        result_expires_at=result_expires_at,
    )


def _cap_chat_results(
    results: QueryResults, *, max_cell_chars: int, max_bytes: int
) -> tuple[QueryResults, bool]:
    """チャットの実行の結果をセルの文字数と応答のバイト数の上限で切る（#1154）。

    文字数の上限を超えたセルは先頭だけにして末尾に「…」を付ける。行の JSON の合計が `max_bytes` を
    超えたら、その行から後ろは返さず打ち切り（`has_more` / `truncated`）にする。返り値の 2 つ目は
    文字を切ったセルがあるか。
    """

    cells_truncated = False
    rows: list[dict[str, Any]] = []
    used = 0
    bytes_truncated = False
    for row in results.rows:
        capped: dict[str, Any] = {}
        for key, value in row.items():
            if isinstance(value, str) and len(value) > max_cell_chars:
                value = value[:max_cell_chars] + "…"
                cells_truncated = True
            capped[key] = value
        size = len(json.dumps(capped, ensure_ascii=False, default=str).encode("utf-8")) + 1
        if used + size > max_bytes:
            bytes_truncated = True
            break
        used += size
        rows.append(capped)
    incomplete = bool(results.has_more or results.truncated or bytes_truncated)
    return (
        results.model_copy(
            update={
                "rows": rows,
                "total": len(rows),
                "returned_count": len(rows),
                "has_more": incomplete,
                "truncated": incomplete,
            }
        ),
        cells_truncated,
    )


_TEMPLATE_XLSX_UPLOAD_MESSAGE = (
    "ダウンロードした .xlsx テンプレートファイルをアップロードしてください。"
)
_EXCEL_ILLEGAL_CHARACTERS_RE = re.compile(r"[\x00-\x08\x0B-\x0C\x0E-\x1F]")


def _require_xlsx_template_upload(filename: str) -> None:
    """Excel 出力と対になるテンプレート取込は .xlsx のみ受け付ける。"""

    if Path(filename).suffix.lower() != ".xlsx":
        raise ValueError(_TEMPLATE_XLSX_UPLOAD_MESSAGE)


def _excel_safe_text(value: Any) -> str:
    """Excel 書き出し時に式評価と不正制御文字を避ける文字列へ寄せる。"""

    return _EXCEL_ILLEGAL_CHARACTERS_RE.sub("", str(value if value is not None else ""))


def _append_excel_text_row(sheet: Any, values: Sequence[Any]) -> None:
    sheet.append([_excel_safe_text(value) for value in values])
    for cell in sheet[sheet.max_row]:
        cell.data_type = "s"


def _db_admin_error(
    exc: Exception,
    *,
    target_name: str = "",
    target_type: str = "",
    operation: str = "",
) -> DbAdminOperationFailed:
    """Oracle 例外を、DB 管理で共通利用する日本語の復旧情報へ変換する。"""
    code = _safe_oracle_error_code(exc) or "oracle_operation_failed"
    raw_message = str(exc)
    known: dict[str, tuple[str, str, list[str]]] = {
        "ORA-01031": (
            "権限が不足しています。",
            "この操作を実行する Oracle 権限がありません。",
            [
                "実行ユーザーの CREATE / ALTER / DROP または対象表への権限を"
                "管理者に確認してください。"
            ],
        ),
        "ORA-00942": (
            "対象の表またはビューが見つかりません。",
            "対象が存在しないか、参照権限がありません。",
            ["対象名、schema owner、実行ユーザーの権限を確認してください。"],
        ),
        "ORA-00904": (
            "列名または識別子が無効です。",
            "存在しない列名、または Oracle で解釈できない識別子が指定されています。",
            ["SQL と表定義の列名・引用符・alias を確認してください。"],
        ),
        "ORA-00922": (
            "Oracle SQL の構文が無効です。",
            "句、括弧、カンマ、または複数 SQL の区切りが Oracle 構文に合っていません。",
            ["SQL プレビューを確認し、文ごとに実行してください。"],
        ),
        "ORA-01722": (
            "数値形式が正しくありません。",
            "数値列へ文字列を渡した、または数値変換できない値が含まれています。",
            ["対象列のデータ型とファイルまたは SQL の値を確認してください。"],
        ),
        "ORA-01843": (
            "日付の月が正しくありません。",
            "指定した日付値を Oracle が解釈できません。",
            ["日付を YYYY-MM-DD など表定義に合う形式へ修正してください。"],
        ),
        "ORA-01861": (
            "日付または時刻の形式が一致しません。",
            "値の書式が対象列または変換書式と一致していません。",
            ["日付・時刻の書式と対象列の型を確認してください。"],
        ),
        "ORA-12899": (
            "値が列の最大長を超えています。",
            "文字列またはバイト数が対象列の上限を超えています。",
            ["値を短くするか、対象列の長さを拡張してください。"],
        ),
        "ORA-00001": (
            "一意制約に違反しています。",
            "同じ主キーまたは一意キーの値が既に存在します。",
            ["重複する値を修正するか、既存データを確認してください。"],
        ),
        "ORA-01400": (
            "必須列に値がありません。",
            "NOT NULL の列へ NULL または空の値を登録しようとしました。",
            ["ファイルまたは SQL に必須列の値を設定してください。"],
        ),
        "ORA-02291": (
            "参照先データが存在しません。",
            "外部キーが参照する親データが未登録です。",
            ["親テーブルのデータを先に登録し、外部キー値を確認してください。"],
        ),
        "ORA-02292": (
            "参照されているデータは削除できません。",
            "子テーブルのデータが対象行を参照しています。",
            ["参照データを確認し、必要なら子データを先に処理してください。"],
        ),
        "ORA-00054": (
            "対象が他の処理で使用中です。",
            "ロック競合のため操作を完了できませんでした。",
            ["他の更新処理の完了後に再試行してください。"],
        ),
    }
    if code == "ORA-00955":
        object_description = (
            f"既存の{target_type}" if target_type else "同名のデータベースオブジェクト"
        )
        name = f"「{target_name}」" if target_name else "指定した名前"
        return DbAdminOperationFailed(
            error_code=code,
            summary=f"{name} は既に存在するため、新規作成できません。",
            cause=f"{object_description} と名前が重複しています。",
            actions=[
                "表名を変更して再実行してください。",
                "一覧へ戻り、同名の既存オブジェクトを確認してください。",
            ],
            target_name=target_name,
            target_type=target_type,
            operation=operation,
            raw_message=raw_message,
        )
    if code in _ORACLE_CONNECTION_CODES or _is_oracle_connection_failure(exc):
        return DbAdminOperationFailed(
            error_code=code,
            summary="Oracle データベースに接続できません。",
            cause="接続設定、ネットワーク、またはデータベースの稼働状態に問題がある可能性があります。",
            actions=[
                "データベース接続状態を確認してから再試行してください。",
                "解消しない場合は管理者に接続設定を確認してください。",
            ],
            target_name=target_name,
            target_type=target_type,
            operation=operation,
            raw_message=raw_message,
        )
    if code in known:
        summary, cause, actions = known[code]
    else:
        summary = f"データベース処理に失敗しました（{code}）。"
        cause = "Oracle 側で処理を完了できませんでした。"
        actions = ["対象 SQL または取込データ、実行権限、データベース状態を確認してください。"]
    return DbAdminOperationFailed(
        error_code=code,
        summary=summary,
        cause=cause,
        actions=actions,
        target_name=target_name,
        target_type=target_type,
        operation=operation,
        raw_message=raw_message,
    )


def _is_oracle_connection_failure(exc: Exception) -> bool:
    code = _safe_oracle_error_code(exc)
    if code in _ORACLE_CONNECTION_CODES:
        return True
    if code.startswith(("ORA-121", "ORA-122", "ORA-125", "ORA-126", "DPY-4", "DPY-6")):
        return True
    exception_type = type(exc).__name__.lower()
    detail = str(exc).lower()
    return (
        exception_type in {"operationalerror", "interfaceerror"}
        or "timed out" in detail
        or "timeout" in detail
    )


