class ChatConversationBusyError(ValueError):
    """SQL の生成中のターンがある会話は、名前の変更・削除をしない（#1817）。"""


class OthersContentForbiddenError(Exception):
    """system_admin が他の利用者の会話・実行に、新しい実行・内容を足そうとした（#3244）。

    続きの質問・SQL の実行・回答前の確認への回答・評価・名前の変更は持ち主だけ。見えるデータなので
    404 にせず 403（`OTHERS_CONTENT_FORBIDDEN_STATUS`）にする。404 にする `PermissionError` と
    混ざらないよう、`PermissionError` / `ValueError` を継承しない。
    """

    def __init__(self) -> None:
        super().__init__(OTHERS_CONTENT_FORBIDDEN_MESSAGE)


# 会話の名前の上限（RAG・Agent の会話名と同じ。#1817）。
SQL_CHAT_TITLE_MAX_LENGTH = 80


@dataclass
class StoredJob:
    job_id: str
    request: JobCreateRequest
    actor_user_uuid: str = ""
    actor_is_system_admin: bool = False
    business_release_id: str = ""
    # 業務のオントロジーの公開版（business_release_id）を worker がまだ確定していないか。
    # 投入の要求の中では確定せず（オントロジーの runtime の lock と DB の読み取りで投入を
    # 塞がない）、worker の prepare_context の段階で確定する。旧版の snapshot（印が無い）は
    # 投入時に確定済み。
    business_release_pending: bool = False
    conversation_id: str = ""
    status: JobStatus = JobStatus.PENDING
    created_at: str = field(default_factory=_utc_now)
    started_at: str | None = None
    finished_at: str | None = None
    elapsed_ms: int | None = None
    result: Nl2SqlResult | None = None
    error_message: str | None = None
    error_code: str | None = None
    error_detail: str | None = None
    warning_message: str | None = None
    timing: TimingEnvelope | None = None
    steps: list[JobStepData] = field(default_factory=list)
    worker_id: str = ""
    heartbeat_at: str | None = None
    lease_expires_at: str | None = None
    attempt: int = 0
    # 協調キャンセル要求。worker が stage 境界で検出して JobCancelledError を送出する。
    cancel_requested: bool = False
    # 最初の取消の要求の記録（操作した人と入口。このプロセスで受けた要求だけ。別のプロセスが受けた
    # 要求は取消の要求のドキュメントにある）。停止の実行履歴の行に写す（#3348）。
    cancel_record: dict[str, str] = field(default_factory=dict)
    # 自プロセスの worker スレッドが実行している job か。False は他 worker / 再起動前の
    # snapshot 由来で、in-flight の間は repository を正本として読み直す(永続化しない)。
    owned: bool = False
    execution_owner: tuple[str, int] | None = None
    # チャットのターンの SQL を最後に実行したときの要約（行は持たない。#1154）。
    last_execution: SqlChatExecutionSummary | None = None
    # 会話の名前（利用者が変えたもの。会話の最初のジョブにだけ置く。#1817）。空なら最初の質問。
    chat_title: str = ""
    # 利用者が消した会話のジョブ（#1817）。ジョブは監査・フィードバック・実行履歴のために残し、
    # 会話の一覧・詳細・続きから外す。
    chat_deleted: bool = False
    # チャットのターンの会話の持ち主（投入のときに決める。実行履歴の行に残す。#1954）。
    # 会話でないジョブと、#1954 より前のジョブは空（必要なら最初のターンから引く）。
    conversation_owner_user_uuid: str = ""
    # 実行のきっかけ（MCP の入口が決める。画面のジョブは空。実行履歴の行に残す。#1986）。
    origin: JobOrigin = field(default_factory=JobOrigin)
    # worker の実行の trace の親（MCP の入口の span。サービストークンの要求なら Agent の span の
    # 下）。画面の要求のジョブは空で、worker が新しい trace を始める（#3226）。
    trace_context: dict[str, str] = field(default_factory=dict)
    # 画面の要求の span context（新しい trace の root に span link として結ぶ。表の親子にしない）。
    trace_link_context: dict[str, str] = field(default_factory=dict)
    # 処理の経過（#3226 の案 A）: span は共通の span の表にあり、ジョブには実行の trace id・
    # 書けなかった span の数（実行を確定するときに保存）・工程の詳細（span id → 詳細。表には
    # 入れない内容）を置く。
    trace_id: str = ""
    trace_dropped_spans: int = 0
    span_details: dict[str, dict[str, Any]] = field(default_factory=dict)


@dataclass(frozen=True)
class JobTraceData:
    """ジョブの処理の経過（span の表の snapshot）と、route がアクセスを判定する値。"""

    trace: TraceProgressData
    profile_id: str
    chat: bool


@dataclass(frozen=True)
class GeneratedSqlExecution:
    """生成した SQL の実行の結果（SQL 生成のジョブの実行の段階とチャットの実行で共通。#1154）。

    Oracle のエラーは例外にせず、SQL 生成のジョブと同じ利用者向けの文・エラーコード・詳細に分ける。
    """

    safety: SafetyReport
    executable_sql: str
    results: QueryResults
    error_message: str | None = None
    error_code: str | None = None
    error_detail: str | None = None


_NL2SQL_JOB_STAGES = (
    "prepare_context",
    "generate_sql",
    "safety_check",
    "execute_sql",
    "format_results",
)


def _new_job_steps() -> list[JobStepData]:
    return [JobStepData(stage=stage) for stage in _NL2SQL_JOB_STAGES]


# 処理の経過（チャット・SQL 生成・実行履歴の `ChatProgress`）は実行の trace（span の木）の投影
# （#3226）。工程の span（開始待ち `queue` とジョブの 5 段階）は表示用のデータ（`SpanDisplay`）の
# `kind` に段階の id を持ち、名前は画面の段階の定義が付ける。
_JOB_PROGRESS_QUEUE_STEP = "queue"
_JOB_PROGRESS_STAGE_KINDS = frozenset({_JOB_PROGRESS_QUEUE_STEP, *_NL2SQL_JOB_STAGES})
# 安全性の確認を省略した印（Select AI / Select AI Agent の SQL。#1523）。
_JOB_PROGRESS_SAFETY_CHECK_SKIPPED_PARAM = "safety_check_skipped"
# 安全性の確認の補足に出す参照した表の数（残りは件数だけ。画面の「ほか N 件」）。
_JOB_PROGRESS_TABLES_SHOWN = 3

type JobProgressParams = dict[str, ChatProgressParamValue]


def _parse_job_time(value: str | None) -> datetime | None:
    """ジョブの時刻（ISO 8601 の文字列）を datetime にする（読めなければ None）。"""

    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=UTC)


def _job_progress_attempt(job: StoredJob) -> int:
    """処理の経過のイベントの試行（最初の実行が 0）。

    ジョブの `attempt` は worker が claim するたびに増える（未着手 0・最初の実行 1）。lease の
    切れたジョブを引き継いだ実行（2 回目以降の claim）から試行を増やし、span の木を作り直す。
    """

    return max(0, job.attempt - 1)


def _job_trace_terminal(job: StoredJob) -> TraceTerminal | None:
    """処理の経過の終端（正本はジョブの状態。SQL の遮断・実行の失敗は失敗、停止は停止）。"""

    if job.status == JobStatus.DONE:
        return "done"
    if job.status == JobStatus.ERROR:
        return "cancelled" if job.error_code == JOB_CANCELLED_ERROR_CODE else "failed"
    return None


def _job_trace_dropped(job: StoredJob) -> int:
    """書けなかった span の数（この process の書き手の数と、保存済みの数の大きい方）。"""

    return max(job.trace_dropped_spans, trace_span_dropped(job.trace_id))


def _with_requirement_usage(
    usage: RunModelUsage | None, request: JobCreateRequest
) -> RunModelUsage | None:
    """ジョブの利用量に、回答前の確認の LLM の呼び出しの利用量を足す（#3552）。

    確認の要求はジョブの trace の外なので、確認の session が集めた利用量を反映した要件
    （`sql_requirement.usage`）で受け取る。確認を経ないジョブと、確認の利用量の記録が無いジョブ
    （この機能より前の session）は、ジョブの利用量のまま。ジョブの記録が無い（trace の始まる前に
    止まった）ときは、確認の分だけを一部計測として残す（ジョブの呼び出しは数えていない）。
    """

    requirement = request.sql_requirement.usage if request.sql_requirement is not None else None
    if requirement is None:
        return usage
    if usage is None:
        return requirement.model_copy(update={"measurement": "partial"})
    return add_run_usage(usage, requirement)


_TRACE_ID_RE = re.compile(r"^[0-9a-f]{32}$")


def _trace_id_of(value: object) -> str:
    """保存した trace id（形の違う値は捨てる）。"""

    return value if isinstance(value, str) and _TRACE_ID_RE.fullmatch(value) else ""


def _non_negative_int(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        return 0
    try:
        return max(0, int(value))
    except ValueError:
        return 0


def _span_details_of(value: object) -> dict[str, dict[str, Any]]:
    """保存した工程の詳細（span id → 詳細）。

    形の違う要素は捨てる。中身は読むときに共通の規則で検証する。
    """

    if not isinstance(value, Mapping):
        return {}
    return {
        str(key): dict(item)
        for key, item in value.items()
        if isinstance(key, str) and isinstance(item, Mapping)
    }


def _record_job_span_details(job: StoredJob, update: SpanUpdate) -> None:
    """span の工程の詳細をジョブに置く。

    呼ぶ側はジョブの lock の中で呼ぶ。保存は続く保存に任せる。
    """

    details = span_details_of(update)
    if details is not None:
        job.span_details[update.span_id] = details


def _job_progress_tables_params(tables: Sequence[str]) -> JobProgressParams | None:
    """安全性の確認の補足: 参照した表（先頭の数件）と表の数。"""

    names = [name for name in tables if name]
    if not names:
        return None
    return {
        "tables": ", ".join(names[:_JOB_PROGRESS_TABLES_SHOWN]),
        "table_count": len(names),
    }


# 段を開いて見る詳細（#2294）。利用者がチャットで見られる値（書き換えた質問・SQL・安全性の
# 確認の結果・行数）だけを入れる（接続・資格情報・Oracle のエラーの全文は入れない。失敗の原因は
# 回答の場所の Banner が出す）。長さは `ChatProgressStepDetails` が上限で切り、秘密を伏せる。


def _job_progress_prepare_details(
    question: str, rewritten: str, row_limit: int | None
) -> ChatProgressStepDetails | None:
    """準備の段階の詳細: 書き換えた質問（元と違うときだけ）と行数の上限。"""

    changed = rewritten.strip() and rewritten.strip() != question.strip()
    return chat_progress_details(
        fields=[
            ("生成に使った質問", rewritten.strip() if changed else None),
            ("取得する行数の上限", row_limit),
        ]
    )


def _job_progress_generate_details(generated: GeneratedSql) -> ChatProgressStepDetails | None:
    """SQL の生成の段階の詳細: 生成した SQL と、別の方法に切り替えた理由。"""

    return chat_progress_details(
        fields=[("切り替えた理由", generated.fallback_reason or None)],
        code=[("生成した SQL", generated.generated_sql, "sql")],
    )


def _job_progress_safety_details(safety: SafetyReport) -> ChatProgressStepDetails | None:
    """安全性の確認の段階の詳細: 結果・遮断の理由・参照した表と列・警告。"""

    if not safety.safety_checked:
        result = "確認を省略"
    elif safety.is_safe:
        result = "安全"
    else:
        result = "遮断"
    tables = [name for name in safety.referenced_tables if name]
    columns = [name for name in safety.referenced_columns if name]
    return chat_progress_details(
        fields=[
            ("結果", result),
            ("遮断の理由", safety.blocked_reason or None),
            ("省略の理由", safety.safety_check_skip_reason or None),
            ("参照した表", ", ".join(tables) or None, True),
            ("参照した列", ", ".join(columns) or None, True),
            ("適用した行数の上限", safety.row_limit_applied or None),
        ],
        lines=[warning for warning in safety.warnings if warning],
    )


def _job_progress_execute_details(results: QueryResults) -> ChatProgressStepDetails | None:
    """SQL の実行の段階の詳細: 取得した行数・列数と、上限で打ち切ったか。"""

    columns = len(results.columns)
    return chat_progress_details(
        fields=[
            ("取得した行数", f"{results.total:,} 行"),
            ("列数", f"{columns:,} 列" if columns else None),
            ("続きの行", "あり（上限で打ち切り）" if results.has_more else None),
        ]
    )


def _job_safety_check_status(safety: SafetyReport) -> JobStepStatus:
    """安全性の確認の段階の状態（#1523）。

    遮断は失敗。Select AI / Select AI Agent の SQL で安全確認を省略したときは「省略」。
    """

    if not safety.is_safe:
        return JobStepStatus.ERROR
    return JobStepStatus.DONE if safety.safety_checked else JobStepStatus.SKIPPED


def _job_progress_safety_params(safety: SafetyReport) -> JobProgressParams | None:
    """安全性の確認の補足: 参照した表と、安全確認を省略した印（`safety_check_skipped`）。"""

    params = _job_progress_tables_params(safety.referenced_tables)
    if safety.safety_checked:
        return params
    return {**(params or {}), _JOB_PROGRESS_SAFETY_CHECK_SKIPPED_PARAM: True}


def _log_job_stage_started(job_id: str, stage: str, *, attempt: int) -> None:
    """worker の段階の開始（質問・SQL の本文は出さない）。"""

    logger.info(
        "nl2sql_job_stage_started",
        extra={"job_id": job_id, "stage": stage, "attempt": attempt},
    )


def _log_job_stage_finished(
    job_id: str,
    stage: str,
    *,
    status: JobStepStatus,
    elapsed_ms: int | None,
    attempt: int,
) -> None:
    """worker の段階の終了と所要時間（質問・SQL の本文は出さない）。"""

    logger.info(
        "nl2sql_job_stage_finished",
        extra={
            "job_id": job_id,
            "stage": stage,
            "status": status.value,
            "elapsed_ms": elapsed_ms,
            "attempt": attempt,
        },
    )


def _log_job_stage_step_finished(
    job_id: str, stage: str, step: str, *, started: float, attempt: int, skip_reason: str = ""
) -> None:
    """段階の中の処理ごとの所要時間（どの処理が遅いかを追う。#1155）。

    処理を飛ばしたときは `skipped` と `skip_reason` を付ける（例: 公開されたオントロジーが無い
    ため接地確認をしない `no_published_ontology`。#1168。要求が接地確認を求めない
    `grounding_not_requested`。#1172）。質問・SQL の本文は出さない。
    """

    extra: dict[str, Any] = {
        "job_id": job_id,
        "stage": stage,
        "step": step,
        "elapsed_ms": _elapsed_ms(started),
        "attempt": attempt,
    }
    if skip_reason:
        extra["skipped"] = True
        extra["skip_reason"] = skip_reason
    logger.info("nl2sql_job_stage_step_finished", extra=extra)


def _job_failure_step_index(steps: list[JobStepData]) -> int | None:
    for expected_status in (JobStepStatus.RUNNING, JobStepStatus.PENDING):
        for index, step in enumerate(steps):
            if step.status == expected_status:
                return index
    return None


def _normalize_terminal_step_order(steps: list[JobStepData]) -> list[JobStepData]:
    """後続 done の手前に残った in-flight 表示を工程順に完了へ寄せる(error 境界は越えない)。"""

    last_done_index = max(
        (index for index, step in enumerate(steps) if step.status == JobStepStatus.DONE),
        default=-1,
    )
    if last_done_index <= 0:
        return steps
    first_error_index = next(
        (index for index, step in enumerate(steps) if step.status == JobStepStatus.ERROR),
        -1,
    )
    fill_until_index = (
        first_error_index if 0 <= first_error_index < last_done_index else last_done_index
    )
    normalized: list[JobStepData] = []
    for index, step in enumerate(steps):
        if index < fill_until_index and step.status in {
            JobStepStatus.PENDING,
            JobStepStatus.RUNNING,
        }:
            step = step.model_copy(update={"status": JobStepStatus.DONE})
        normalized.append(step)
    return normalized


def _restore_job_status(status: JobStatus, result: Nl2SqlResult | None) -> JobStatus:
    """result 済み snapshot が in-flight のまま残った場合は終端状態へ復元する。"""

    if result is None or status not in _IN_FLIGHT_JOB_STATUSES:
        return status
    return JobStatus.DONE if result.safety.is_safe else JobStatus.ERROR


def _restore_job_steps(
    raw_steps: list[dict[str, Any]],
    *,
    status: JobStatus,
    timing: TimingEnvelope | None,
    has_result: bool,
) -> list[JobStepData]:
    """旧 snapshot の3段階 timing も現在の5段階契約へ正規化する。"""

    parsed = [JobStepData.model_validate(step) for step in raw_steps]
    by_stage = {step.stage: step for step in parsed}
    legacy_step = by_stage.get("safety_and_execute")
    timing_by_stage = (
        {item.stage: item.elapsed_ms for item in timing.stage_timings} if timing else {}
    )
    legacy_elapsed = timing_by_stage.get("safety_and_execute")
    restored: list[JobStepData] = []

    for stage in _NL2SQL_JOB_STAGES:
        step = by_stage.get(stage)
        if step is not None:
            restored.append(step)
            continue
        if stage in {"safety_check", "execute_sql"} and legacy_step is not None:
            legacy_status = legacy_step.status
            if status == JobStatus.ERROR:
                legacy_status = (
                    JobStepStatus.ERROR if stage == "safety_check" else JobStepStatus.SKIPPED
                )
            restored.append(
                legacy_step.model_copy(update={"stage": stage, "status": legacy_status})
            )
            continue
        elapsed_ms = timing_by_stage.get(stage)
        if elapsed_ms is None and stage in {"safety_check", "execute_sql"}:
            elapsed_ms = legacy_elapsed
        completed = elapsed_ms is not None or status == JobStatus.DONE
        if stage == "format_results" and has_result:
            completed = True
        restored.append(
            JobStepData(
                stage=stage,
                status=JobStepStatus.DONE if completed else JobStepStatus.PENDING,
                elapsed_ms=elapsed_ms,
            )
        )

    if status == JobStatus.ERROR and not any(
        step.status == JobStepStatus.ERROR for step in restored
    ):
        safety_index = _NL2SQL_JOB_STAGES.index("safety_check")
        execute_index = _NL2SQL_JOB_STAGES.index("execute_sql")
        if legacy_elapsed is not None or timing_by_stage.get("safety_check") is not None:
            restored[safety_index] = restored[safety_index].model_copy(
                update={"status": JobStepStatus.ERROR}
            )
            restored[execute_index] = restored[execute_index].model_copy(
                update={"status": JobStepStatus.SKIPPED}
            )
        else:
            failure_index = _job_failure_step_index(restored)
            if failure_index is not None:
                restored[failure_index] = restored[failure_index].model_copy(
                    update={"status": JobStepStatus.ERROR}
                )
    return _normalize_terminal_step_order(restored)


class HistoryNotRatableError(ValueError):
    """評価できない実行履歴の行（停止の行。SQL・実行結果を持たない。#3348）。"""


def _raise_if_history_not_ratable(item: HistoryItem) -> None:
    if item.run_status == HISTORY_RUN_STATUS_CANCELLED:
        raise HistoryNotRatableError("停止した実行は SQL と実行結果が無いため評価できません。")


def _history_item_matches_payload_filters(
    item: HistoryItem,
    filters: Mapping[str, str],
    *,
    any_filters: Mapping[str, str] | None = None,
    exclude_filters: Mapping[str, str] | None = None,
    present_filters: Mapping[str, bool] | None = None,
) -> bool:
    """memory 実装向けに repository の payload filter(top-level key の文字列一致)を再現する。

    `any_filters`（OR）と `exclude_filters`（一致しない）は repository と同じ意味（#1954）、
    `present_filters`（値が空でない / 空）も同じ（#1955）。
    """

    if not filters and not any_filters and not exclude_filters and not present_filters:
        return True
    return state_document_payload_matches(
        item.model_dump(mode="json"),
        payload_filters=filters,
        payload_any_filters=any_filters,
        payload_exclude_filters=exclude_filters,
        payload_present_filters=present_filters,
    )


# 実行履歴の共通の絞り込み（#1955。run-history.md）。状態は NL2SQL が写せる 2 つ（完了 = 安全性の
# 判定を通過、ブロック = 実行を止めた）、種類はチャットの往復（会話の持ち主あり）・SQL 生成
# （画面）・MCP・品質評価（#1986）。`not_evaluation` は品質評価の行を除く（画面の既定
# 「品質評価以外」）。
HISTORY_KIND_NOT_EVALUATION = "not_evaluation"
HISTORY_KIND_FILTERS = ("all", HISTORY_KIND_NOT_EVALUATION, "chat", "query", "mcp", "evaluation")
HISTORY_STATUS_FILTERS = ("all", "succeeded", "blocked", HISTORY_RUN_STATUS_CANCELLED)
# 停止の行（#3348）。安全性の判定・評価を持たないので、完了・ブロック・フィードバックの一覧から
# 除く。
_HISTORY_CANCELLED_FILTER = {"run_status": HISTORY_RUN_STATUS_CANCELLED}
_HISTORY_EVALUATION_FILTER = {"run_source": RUN_SOURCE_EVALUATION}


def history_kind_filters(
    kind: str,
) -> tuple[dict[str, str], dict[str, str], dict[str, bool]]:
    """種類の絞り込みの payload 条件（一致・除外・値の有無。#1955・#1986）。

    チャットは会話の持ち主がある行、SQL 生成は会話の持ち主もきっかけも無い画面の行、MCP・品質評価は
    きっかけ（`run_source`）が一致する行。`not_evaluation` は品質評価の行を除く（きっかけの無い
    #1986 より前の行は除かない）。
    """
    if kind == "chat":
        return {}, {}, {"conversation_owner_user_uuid": True}
    if kind == "query":
        return {}, {}, {"conversation_owner_user_uuid": False, "run_source": False}
    if kind in (RUN_SOURCE_MCP, RUN_SOURCE_EVALUATION):
        return {"run_source": kind}, {}, {}
    if kind == HISTORY_KIND_NOT_EVALUATION:
        return {}, dict(_HISTORY_EVALUATION_FILTER), {}
    return {}, {}, {}


def normalize_history_since(since: str) -> str:
    """期間の開始（ISO 8601）を、保存の実行日時と同じ形（UTC の `isoformat()`）にする（#1955）。

    空は条件なし。読めない値・タイムゾーンの無い値は ValueError（422）。
    """
    value = since.strip()
    if not value:
        return ""
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("since が不正です。") from exc
    if parsed.tzinfo is None:
        raise ValueError("since が不正です。")
    return parsed.astimezone(UTC).isoformat()


def history_visibility_filters(
    *,
    viewer_user_uuid: str,
    all_users: bool,
    executor: RunExecutorFilter = DEFAULT_RUN_EXECUTOR_FILTER,
) -> tuple[dict[str, str], dict[str, str], dict[str, str]]:
    """実行履歴の見え方と「実行者」の絞り込みの payload 条件（AND・OR・除外。#1954）。

    行は実行した人（`actor_user_uuid`）と会話の持ち主（`conversation_owner_user_uuid`）の
    両方に見える（system_admin〔`all_users`〕は全員の行）。判定は
    `pr_system_settings.auth.visibility.can_access_run` / `run_executor_matches` と同じ範囲:
    `mine` は自分が実行した行、`others` は自分以外が実行した行（実行した人の記録の無い行を含む）。
    """
    any_filters: dict[str, str] = {}
    if not all_users:
        # 利用者が分からないときは何も見せない（値が空の OR はどれにも一致しない）。
        any_filters = {
            "actor_user_uuid": viewer_user_uuid,
            "conversation_owner_user_uuid": viewer_user_uuid,
        }
    filters: dict[str, str] = {}
    exclude_filters: dict[str, str] = {}
    if viewer_user_uuid:
        if executor == "mine":
            filters["actor_user_uuid"] = viewer_user_uuid
        elif executor == "others":
            exclude_filters["actor_user_uuid"] = viewer_user_uuid
    elif executor == "others":
        # 利用者の無い要求（認証無効）はすべての行を自分の実行とみなす（「他の人が実行」は 0 件）。
        any_filters = {"actor_user_uuid": ""}
    return filters, any_filters, exclude_filters


def _history_item_search_text(item: HistoryItem) -> str:
    return " ".join([item.question, item.generated_sql, item.feedback_comment])


# reverse deep で LLM から受け取る処理手順の上限(長大な配列をそのまま保持しない)。
_REVERSE_DEEP_MAX_STEPS = 20


def _reverse_deep_steps(raw: object) -> list[str]:
    """LLM 応答の logical_steps を空要素除去・件数上限付きの文字列 list に正規化する。"""

    if not isinstance(raw, list):
        return []
    steps = [str(item).strip() for item in raw if str(item).strip()]
    return steps[:_REVERSE_DEEP_MAX_STEPS]


def _reverse_deep_step_details(
    steps: Sequence[str],
    deterministic_details: Sequence[Nl2SqlLogicalStep],
) -> list[Nl2SqlLogicalStep]:
    """LLM の手順を業務行にした details を作る。

    件数が決定論版と一致するときだけ technical(技術行)と kind を対応付け、一致しない
    ときは業務行だけにする(位置のずれた技術行を並べて誤解させない)。
    """

    aligned = len(deterministic_details) == len(steps)
    return [
        Nl2SqlLogicalStep(
            kind=deterministic_details[index].kind if aligned else "llm",
            business=step,
            technical=deterministic_details[index].technical if aligned else "",
        )
        for index, step in enumerate(steps)
    ]


